// Datas de referencia (UTC, meia-noite)
const hoje = new Date();
hoje.setUTCHours(0,0,0,0);
const ontem = new Date(hoje);
ontem.setUTCDate(hoje.getUTCDate() - 1);
const inicio7d = new Date(hoje);
inicio7d.setUTCDate(hoje.getUTCDate() - 7);

function toDateOnly(str) {
  return new Date(String(str).slice(0,10) + 'T00:00:00Z');
}

// --- DISPAROS ---
const disparos = $('Disparos - Ler Dados').all().map(i => i.json);
const tipos = ['6.01-fup-atrasados', '6.03-calendar', 'SDR-INBOUND'];

const disparosOntemPorTipo = {};
const disparos7dPorTipo = {};
for (const tipo of tipos) {
  disparosOntemPorTipo[tipo] = 0;
  disparos7dPorTipo[tipo] = 0;
}
let disparosOntemTotal = 0;
let disparos7dTotal = 0;

for (const d of disparos) {
  const dia = toDateOnly(d.dia);
  const enviados = Number(d.disparos_enviados) || 0;

  if (dia.getTime() === ontem.getTime()) {
    disparosOntemPorTipo[d.origem] = (disparosOntemPorTipo[d.origem] || 0) + enviados;
    disparosOntemTotal += enviados;
  }
  if (dia >= inicio7d && dia < hoje) {
    disparos7dPorTipo[d.origem] = (disparos7dPorTipo[d.origem] || 0) + enviados;
    disparos7dTotal += enviados;
  }
}

// --- RESPOSTAS ---
const respostas = $('Respostas - Ler Dados').all().map(i => i.json);
let respostasHoje = 0;
let respostas7d = 0;

for (const r of respostas) {
  const dia = toDateOnly(r.dia);
  const qtd = Number(r.leads_que_responderam) || 0;
  if (dia.getTime() === hoje.getTime()) respostasHoje += qtd;
  if (dia >= inicio7d && dia < hoje) respostas7d += qtd;
}

const taxaRespostaOntem = disparosOntemTotal > 0 ? (respostasHoje / disparosOntemTotal * 100) : 0;
const taxaResposta7d = disparos7dTotal > 0 ? (respostas7d / disparos7dTotal * 100) : 0;

// --- CALLS NOVOS (criados ontem / ultimos 7 dias) ---
const callsCriados = $('Calls Criados - Ler Dados').all().map(i => i.json);
let callsCriadosOntem = 0;
let callsCriados7d = 0;

for (const c of callsCriados) {
  if (!c.created_at) continue;
  const criado = new Date(c.created_at);
  const criadoDia = new Date(Date.UTC(criado.getUTCFullYear(), criado.getUTCMonth(), criado.getUTCDate()));
  if (criadoDia.getTime() === ontem.getTime()) callsCriadosOntem++;
  if (criadoDia >= inicio7d && criadoDia < hoje) callsCriados7d++;
}

// --- CALLS AGENDADOS PARA O FUTURO (bloco separado) ---
const reunioes = $('Reunioes - Ler Dados').all().map(i => i.json);
let callsFuturos = 0;
for (const r of reunioes) {
  const dia = toDateOnly(r.dia);
  if (r.status === 'agendada' && dia >= hoje) {
    callsFuturos += Number(r.quantidade) || 0;
  }
}

return [{
  json: {
    disparos_ontem_total: disparosOntemTotal,
    disparos_ontem_601: disparosOntemPorTipo['6.01-fup-atrasados'],
    disparos_ontem_603: disparosOntemPorTipo['6.03-calendar'],
    disparos_ontem_inbound: disparosOntemPorTipo['SDR-INBOUND'],
    disparos_7d_total: disparos7dTotal,
    disparos_7d_601: disparos7dPorTipo['6.01-fup-atrasados'],
    disparos_7d_603: disparos7dPorTipo['6.03-calendar'],
    disparos_7d_inbound: disparos7dPorTipo['SDR-INBOUND'],
    respostas_hoje: respostasHoje,
    respostas_7d: respostas7d,
    taxa_resposta_ontem: taxaRespostaOntem.toFixed(1),
    taxa_resposta_7d: taxaResposta7d.toFixed(1),
    calls_criados_ontem: callsCriadosOntem,
    calls_criados_7d: callsCriados7d,
    calls_futuros_agendados: callsFuturos
  }
}];

